function sinDeg(d){ return Math.sin(d*Math.PI/180); }

const A = 3;      // amplitude
const a = 1;      // frequency multiplier

const T = 360 / a; // one full period in degrees
console.log('A=',A,'a=',a,'T(one period)=',T,'degrees');

// sample points across one period
const steps = [0, T/4, T/2, 3*T/4, T];
for (const x of steps){
  const y = A * sinDeg(a * x);
  console.log('x=', x.toFixed(2), 'y=', y.toFixed(4));
}

// quick checks
const max = A;
const min = -A;
