function sinDeg(d){ return Math.sin(d*Math.PI/180); }

const A = -2;
const a = 2;
const b = 60;  // phase shift in degrees inside sin(ax + b)
const c = 1;   // vertical shift outside

const samples = [0, 15, 30, 45, 60, 90, 120, 150, 180, 210, 240, 270, 300, 330, 360];

function yOriginal(x){
  return A * sinDeg(a*x + b) ;
}
function yShifted(x){
  return A * sinDeg(a*x + b) + c;
}

console.log('Params:',{A,a,b,c});
console.log('Comparing y = A sin(a x + b) vs y = A sin(a x + b) + c');
for (const x of samples){
  const y1 = yOriginal(x);
  const y2 = yShifted(x);
  console.log('x=',x,'y_base=',y1.toFixed(4),'y_shifted=',y2.toFixed(4),'delta=',(y2-y1).toFixed(4));
}

// y-intercept at x=0
const yInt = yShifted(0);
console.log('y-intercept at x=0 =>', yInt.toFixed(4));
